    const typeLabel=sale.saleType==='internalUse'?'å…§éƒ¨è€—ç”¨ï¼å ±å»¢ç´€éŒ„':sale.saleType==='preorder'&&sale.fulfillmentStatus!=='delivered'?'é è³¼è¨‚å–®':'éŠ·å”®è¨‚å–®';
